const env = $('Read envelope').first().json;
const c = $('Prepare run').first().json;
const v = $('Decide').first().json;
const tx = $('Chain call').first().json;
const message = v.approve
  ? `Reviewer ${c.reviewer} approved: tests pass, diff stays in scope`
  : `Reviewer ${c.reviewer} rejected: ${v.failed.concat(v.suspicious ? ['suspicious'] : []).join(', ')}`;
return [{ json: {
  runId: env.runId, ownerId: c.buyer_id, agentId: c.reviewer_agent_id, jobId: c.job_id,
  actorLabel: `Reviewer ${c.reviewer}`, message, severity: v.approve ? 'ok' : 'block',
  data: { deliveryId: c.delivery_id, approve: v.approve, failed: v.failed,
          logHash: v.logHash, attestationHash: v.attestationHash, voteTx: tx.txHash },
  notify: { runId: env.runId, role: 'reviewer', ok: true, jobId: c.job_id,
            result: { deliveryId: c.delivery_id, reviewer: c.reviewer, approve: v.approve,
                      voteTx: tx.txHash, voteOk: tx.ok }, error: null },
} }];
